/**
 * 解析 - Dockhand
 * 识别容器/Stack/环境/批量更新/镜像清理等事件，镜像图标走 selfh.st 索引（缓存 24 小时）
 */

// ======================= 可配置图标 =======================
// selfh.st 图标索引地址（缓存 24 小时）与 PNG 图标目录前缀
const SELFHST_INDEX_URL = "https://cdn.jsdelivr.net/gh/selfhst/icons/index.json";
const SELFHST_ICON_BASE = "https://cdn.jsdelivr.net/gh/selfhst/icons/png";
// 未匹配到镜像图标时的默认图标名（对应 ${SELFHST_ICON_BASE}/docker.png）
const DOCKHAND_DEFAULT_ICON_REF = "docker";
// =========================================================

const str = (v) => (v === null || v === undefined ? "" : String(v));
let testMode = false;
const utf8Bytes = (ch) => {
    const cp = ch.codePointAt(0);
    if (cp <= 0x7f) return 1;
    if (cp <= 0x7ff) return 2;
    if (cp <= 0xffff) return 3;
    return 4;
};
const clipUtf8 = (text, maxBytes, suffix = "") => {
    const s = str(text);
    let total = 0;
    for (const ch of s) total += utf8Bytes(ch);
    if (total <= maxBytes) return s;
    let suffixBytes = 0;
    for (const ch of suffix) suffixBytes += utf8Bytes(ch);
    const limit = Math.max(0, maxBytes - suffixBytes);
    let used = 0;
    let out = "";
    for (const ch of s) {
        const b = utf8Bytes(ch);
        if (used + b > limit) break;
        out += ch;
        used += b;
    }
    return out.trimEnd() + suffix;
};
const bark = (group, title, body, extra = {}) => {
    const fullTitle = clipUtf8(testMode ? `【🧪测试】 ${title}` : title, 240, "…");
    const safeBody = clipUtf8(body, 2800, "\n…（内容过长已截断）");
    const payload = { group, title: fullTitle, body: safeBody, action: "none" };
    for (const [key, value] of Object.entries(extra)) {
        if (value !== undefined && value !== null && value !== "") payload[key] = value;
    }
    return payload;
};

// 时间统一按 UTC+8 显示，不依赖 n8n 容器的 TZ 设置
const formatTimestamp = (value) => {
    const text = str(value).trim();
    if (!text) return "";
    const d = new Date(text);
    if (Number.isNaN(d.getTime())) return text;
    const hasZone = /(?:Z|[+-]\d{2}:?\d{2})$/i.test(text);
    const t = hasZone ? new Date(d.getTime() + 8 * 3600 * 1000) : d;
    const year = hasZone ? t.getUTCFullYear() : t.getFullYear();
    const month = hasZone ? t.getUTCMonth() + 1 : t.getMonth() + 1;
    const day = hasZone ? t.getUTCDate() : t.getDate();
    const hour = hasZone ? t.getUTCHours() : t.getHours();
    const minute = hasZone ? t.getUTCMinutes() : t.getMinutes();
    const second = hasZone ? t.getUTCSeconds() : t.getSeconds();
    const p = (n) => String(n).padStart(2, "0");
    return `${year} 年 ${p(month)} 月 ${p(day)} 日 ${p(hour)} 时 ${p(minute)} 分 ${p(second)} 秒`;
};

const normalize = (value) =>
    str(value)
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "");

const ICON_ALIAS = {
    postgres: "postgresql",
    pgsql: "postgresql",
    mongo: "mongodb",
    nodered: "node-red",
    "immich-server": "immich",
    "immich-machine-learning": "immich",
    "mastodon-web": "mastodon",
    "mastodon-streaming": "mastodon",
    "mastodon-sidekiq": "mastodon",
    "librespeed-speedtest": "librespeed",
    speedtest: "librespeed",
    "nextcloud-releases": "nextcloud",
    "livekit-server": "livekit",
    "moviepilot-v3": "moviepilot",
    matrixdotorg: "matrix",
    synapse: "matrix"
};

function imageCandidates(image) {
    const out = new Set();
    const add = (value) => {
        const v = normalize(value);
        if (v) out.add(v);
    };
    let ref = str(image).trim();
    if (!ref) return [];
    ref = ref.split("@")[0];
    ref = ref.replace(/:[^/:]+$/, "");
    const parts = ref.split("/").filter(Boolean);
    if (parts.length > 1 && /[.:]/.test(parts[0])) parts.shift();
    const name = parts.pop() || "";
    const path = parts.join("/");

    add(name);
    add(path);
    add(path ? `${path}-${name}` : "");
    for (const segment of path.split("/")) {
        add(segment);
        add(segment.replace(/-releases$/, ""));
    }

    const suffixes = [
        "-server", "-app", "-web", "-api", "-worker", "-service",
        "-db", "-database", "-redis", "-postgres", "-postgresql",
        "-mysql", "-mariadb", "-machine-learning", "-ml", "-aio",
        "-latest", "-v2", "-v3", "-v4"
    ];
    for (const suffix of suffixes) {
        if (name.endsWith(suffix)) add(name.slice(0, -suffix.length));
    }

    const stopwords = new Set([
        "server", "service", "app", "web", "api", "worker", "latest",
        "release", "stable", "alpine", "slim", "base", "core", "main",
        "edge", "proxy", "static", "admin", "users", "push", "gateway",
        "messages", "media", "gifs", "unfurl", "snowflakes", "aio",
        "machine", "learning", "ml", "db", "database"
    ]);
    for (const token of name.split("-")) {
        if (token.length >= 3 && !stopwords.has(token)) add(token);
    }
    return [...out];
}

const n8nContext = this;
const httpRequest =
    n8nContext && n8nContext.helpers && n8nContext.helpers.httpRequest
        ? n8nContext.helpers.httpRequest.bind(n8nContext.helpers)
        : null;

async function dockerIcon(image) {
    const staticData = $getWorkflowStaticData("global");
    let refs = Array.isArray(staticData.selfhstRefs) ? staticData.selfhstRefs : [];
    const stale = !refs.length || !staticData.selfhstAt || Date.now() - staticData.selfhstAt > 24 * 60 * 60 * 1000;
    if (stale && httpRequest) {
        try {
            const data = await httpRequest({
                url: SELFHST_INDEX_URL,
                method: "GET",
                json: true,
                timeout: 10000
            });
            if (Array.isArray(data) && data.length) {
                refs = data.map((item) => item && item.Reference).filter(Boolean);
                staticData.selfhstRefs = refs;
                staticData.selfhstAt = Date.now();
            }
        } catch (e) {
            // 索引拉取失败时保留旧缓存，图标节点继续使用已有 refs
        }
    }

    const refSet = new Set(refs);
    const candidates = imageCandidates(image);
    let ref = "";
    for (const candidate of candidates) {
        if (Object.prototype.hasOwnProperty.call(ICON_ALIAS, candidate)) {
            const target = ICON_ALIAS[candidate];
            if (target && (!refSet.size || refSet.has(target))) {
                ref = target;
                break;
            }
            continue;
        }
        if (refSet.has(candidate)) {
            ref = candidate;
            break;
        }
    }
    if (!ref && refSet.size) {
        const sorted = refs.slice().sort((a, b) => b.length - a.length);
        for (const candidate of candidates) {
            if (candidate.length < 3) continue;
            const hit = sorted.find(
                (r) => r.length >= 3 && (candidate.includes(r) || r.includes(candidate))
            );
            if (hit) {
                ref = hit;
                break;
            }
        }
    }
    if (!ref && !refSet.size && candidates.length) ref = candidates[0];
    return `${SELFHST_ICON_BASE}/${ref || DOCKHAND_DEFAULT_ICON_REF}.png`;
}

const shortText = (text, max = 260) => {
    const clean = str(text).replace(/\s+/g, " ").trim();
    if (!clean) return "";
    return clean.length > max ? `${clean.slice(0, max - 1)}…` : clean;
};

const { kind, payload } = $input.first().json;
testMode = payload.__test === true;
if (kind !== "dockhand") return [];

const rawTitle = str(payload.title).trim() || "Dockhand 通知";
const rawMessage = str(payload.message).trim();
const payloadType = str(payload.type).toLowerCase();
const environment = payload.environment ? str(payload.environment).trim() : "";
const timestamp = payload.timestamp || payload.time || new Date().toISOString();
const pick = (re) => {
    const match = rawMessage.match(re);
    return match ? match[1].trim() : "";
};
const container = pick(/Container\s+"([^"]+)"/i);
const stack = pick(/Stack\s+"([^"]+)"/i);
const envName = pick(/Environment\s+"([^"]+)"/i) || environment;

const raw = `${rawTitle} ${rawMessage}`;
const isBatchUpdates = /updates?\s+available/i.test(raw);
const pruneMatch = rawTitle.match(/^(Image|Container|Volume|Network|System)\s+prune\b/i) ||
    raw.match(/\b(Image|Container|Volume|Network|System)\s+prune\b/i);

// 单容器事件才从括号里提取镜像名；批量更新清单不要误取最后一个镜像
let image = "";
if (!isBatchUpdates && !pruneMatch) {
    const parens = [...rawMessage.matchAll(/\(([^()]+)\)/g)].map((m) => m[1].trim());
    image = parens.reverse().find(
        (value) => /^[a-z0-9][a-z0-9._\/:@-]*$/i.test(value) && /[\/:]/.test(value)
    ) || "";
}

let event = "通知消息";
let emoji = "🔔";
let level = "active";
let subject = "";
let detailText = "";
let updateLines = [];
let showRawTitle = false;

if (/test/i.test(rawTitle)) {
    event = "测试通知";
    emoji = "🧪";
    detailText = "Dockhand 测试通知，收到即表示通知配置正常";
} else if (isBatchUpdates) {
    // 批量容器/镜像可更新清单：解析每行 "- 容器名 (镜像): ..."
    const parsedUpdates = [];
    for (const line of rawMessage.split(/\r?\n/)) {
        const m = line.match(/^\s*-\s+([^\s(]+)(?:\s*\(([^)]+)\))?/);
        if (m) parsedUpdates.push({ name: m[1].trim(), image: (m[2] || "").trim() });
    }
    const countMatch = rawMessage.match(/(\d+)\s+update\(?s?\)?\s+available/i);
    const totalCount = countMatch ? Number(countMatch[1]) : parsedUpdates.length;
    event = totalCount ? `${totalCount} 个容器可更新` : "容器可更新";
    emoji = "📦";
    subject = envName;
    if (parsedUpdates.length === 1 && parsedUpdates[0].image) {
        image = parsedUpdates[0].image;
    }
    const MAX_SHOW = 12;
    if (parsedUpdates.length) {
        updateLines = parsedUpdates
            .slice(0, MAX_SHOW)
            .map((u) => (u.image ? `· ${u.name} (${u.image})` : `· ${u.name}`));
        if (parsedUpdates.length > MAX_SHOW) {
            updateLines.push(`… 其余 ${parsedUpdates.length - MAX_SHOW} 个容器略`);
        }
    } else if (rawMessage) {
        detailText = shortText(rawMessage, 320);
    }
} else if (pruneMatch) {
    const targetMap = {
        image: "镜像",
        container: "容器",
        volume: "卷",
        network: "网络",
        system: "系统"
    };
    const targetLabel = targetMap[pruneMatch[1].toLowerCase()] || "镜像";
    const isFail = payloadType === "error" || /fail|error|timeout|exceeded/i.test(raw);
    if (isFail) {
        event = `${targetLabel}清理失败`;
        emoji = "🚨";
        level = "critical";
        detailText = shortText(rawMessage, 240);
    } else {
        event = `${targetLabel}清理完成`;
        emoji = "🧹";
        const reclaimed = rawMessage.match(
            /(\d+)\s+unused\s+images?\s+removed,\s*([\d.]+\s*[KMGTP]?B)\s+disk\s+space\s+reclaimed/i
        );
        detailText = reclaimed
            ? `已清理 ${reclaimed[1]} 个未使用镜像，释放 ${reclaimed[2]} 空间`
            : shortText(rawMessage, 240);
    }
    subject = envName;
} else if (/unhealthy/i.test(raw)) {
    if (/stack/i.test(raw)) {
        event = "Stack异常";
    } else if (/environment/i.test(raw)) {
        event = "环境异常";
    } else {
        event = "Container异常";
    }
    emoji = "🚨";
    level = "critical";
} else if (/container/i.test(raw)) {
    if (/offline|unreachable|disconnected/i.test(raw)) {
        event = "Container异常";
        emoji = "🚨";
        level = "critical";
    } else if (/healthy/i.test(raw)) {
        event = "Container健康";
        emoji = "✅";
    } else if (/start|launch/i.test(raw)) {
        event = "Container启动";
        emoji = "🟢";
    } else if (/stop|kill|shutdown/i.test(raw)) {
        event = "Container停止";
        emoji = "🟡";
    } else if (/restart/i.test(raw)) {
        event = "Container重启";
        emoji = "🔄";
    } else if (/recreat/i.test(raw)) {
        event = "Container重建";
        emoji = "🛠️";
    } else if (/updat|pull/i.test(raw)) {
        event = "Container更新";
        emoji = "⚡";
    } else if (/remov|delet/i.test(raw)) {
        event = "Container删除";
        emoji = "🗑️";
    } else if (/creat/i.test(raw)) {
        event = "Container创建";
        emoji = "📦";
    } else {
        event = "Container通知";
        showRawTitle = true;
        detailText = shortText(rawMessage, 240);
    }
} else if (/stack/i.test(raw)) {
    if (/offline|unreachable|disconnected/i.test(raw)) {
        event = "Stack异常";
        emoji = "🚨";
        level = "critical";
    } else if (/deploy/i.test(raw)) {
        event = "Stack部署";
        emoji = "🚀";
    } else if (/start/i.test(raw)) {
        event = "Stack启动";
        emoji = "🟢";
    } else if (/stop|down/i.test(raw)) {
        event = "Stack停止";
        emoji = "🟡";
    } else if (/restart/i.test(raw)) {
        event = "Stack重启";
        emoji = "🔄";
    } else if (/recreat/i.test(raw)) {
        event = "Stack重建";
        emoji = "🛠️";
    } else if (/updat|pull/i.test(raw)) {
        event = "Stack更新";
        emoji = "⚡";
    } else if (/remov|delet/i.test(raw)) {
        event = "Stack删除";
        emoji = "🗑️";
    } else if (/creat/i.test(raw)) {
        event = "Stack创建";
        emoji = "📦";
    } else {
        event = "Stack通知";
        showRawTitle = true;
        detailText = shortText(rawMessage, 240);
    }
} else if (/environment/i.test(raw)) {
    if (/offline|unreachable|disconnected/i.test(raw)) {
        event = "环境离线";
        emoji = "🚨";
        level = "critical";
    } else if (/online|reachable|connected/i.test(raw)) {
        event = "环境在线";
        emoji = "🌐";
    } else {
        event = "环境通知";
        showRawTitle = true;
        detailText = shortText(rawMessage, 240);
    }
} else if (/image/i.test(raw) && /(update|available|newer)/i.test(raw)) {
    event = "镜像更新";
    emoji = "📦";
    detailText = shortText(rawMessage, 240);
} else {
    if (payloadType === "error" || /fail|error/i.test(rawTitle)) {
        event = "异常通知";
        emoji = "🚨";
        level = "critical";
    }
    subject = envName;
    showRawTitle = true;
    detailText = shortText(rawMessage, 240);
}

if (!subject) {
    subject = container || stack || (/^环境/.test(event) ? envName : "");
}
const title = `${emoji} ${event}${subject ? " · " + subject : ""}`;
const bodyLines = [];
if (showRawTitle && rawTitle) bodyLines.push(`【原始标题】${rawTitle}`);
if (container) bodyLines.push(`【Container】${container}`);
if (stack) bodyLines.push(`【Stack】${stack}`);
if (image) bodyLines.push(`【镜像】${image}`);
if (envName) bodyLines.push(`【环境】${envName}`);
if (updateLines.length) bodyLines.push(`【更新清单】\n${updateLines.join("\n")}`);
if (detailText) bodyLines.push(`【详情】${detailText}`);
bodyLines.push(`【触发时间】${formatTimestamp(timestamp)}`);

return [
    {
        json: {
            bark: bark("Dockhand", title, bodyLines.join("\n"), {
                icon: await dockerIcon(image),
                level
            }),
            source: "Dockhand",
            event
        }
    }
];
